    fireEvent.change(screen.getByLabelText('Até'), { target: { value: '2026-11-12' } });
    await usuario.click(screen.getByRole('button', { name: 'Bloquear período' }));
    expect(await screen.findByRole('button', { name: 'Bloqueando...' })).toBeDisabled();
